const defaults=()=>({version:1,theme:'evjf',name:'Notre EVJF dans les Pouilles',people:6,start:'',days:3,arrival:'Bari',budget:400,pace:'slow',transport:'driving',interests:['beach','food','party'],zone:null,plan:[],members:Array.from({length:6},(_,i)=>'Personne '+(i+1)),expenses:[],notes:[],splitLink:''});
