function validate(s){const safeId=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(x);if(!s||s.version!==1||!themes.some(t=>t[0]===s.theme)||typeof s.name!=='string'||s.name.length>80||!Number.isInteger(s.people)||s.people<2||s.people>40||!Number.isInteger(s.days)||s.days<1||s.days>14||!Array.isArray(s.plan)||s.plan.length>14||!Array.isArray(s.members)||s.members.length!==s.people||s.members.some(x=>typeof x!=='string'||!x.trim()||x.length>60)||new Set(s.members).size!==s.people)throw Error('Copie non reconnue');if(typeof s.start!=='string'||(s.start&&!/^\d{4}-\d{2}-\d{2}$/.test(s.start))||!['Bari','Brindisi','Foggia','Libre'].includes(s.arrival)||!['slow','active'].includes(s.pace)||!['driving','transit'].includes(s.transport)||!Number.isFinite(s.budget)||s.budget<0||s.budget>100000||!Array.isArray(s.interests)||s.interests.some(x=>!kinds[x])||!Array.isArray(s.expenses)||!Array.isArray(s.notes)||s.notes.length>1000||s.expenses.length>2000)throw Error('Données invalides');for(const d of s.plan){if(!Array.isArray(d)||d.length>50)throw Error('Programme invalide');for(const p of d){if(!safeId(p.uid)||typeof p.name!=='string'||p.name.length>200||typeof p.desc!=='string'||p.desc.length>4000||typeof p.time!=='string'||(p.lat!=null&&(!Number.isFinite(p.lat)||Math.abs(p.lat)>90))||(p.lon!=null&&(!Number.isFinite(p.lon)||Math.abs(p.lon)>180)))throw Error('Étape invalide')}}for(const e of s.expenses){if(!safeId(e.id)||typeof e.title!=='string'||!Number.isInteger(e.cents)||e.cents<1||e.cents>10000000||!s.members.includes(e.payer)||!Array.isArray(e.who)||!e.who.length||e.who.some(n=>!s.members.includes(n))||new Set(e.who).size!==e.who.length)throw Error('Dépense invalide')}for(const n of s.notes){if(!safeId(n.id)||typeof n.text!=='string'||n.text.length>4000||!['private','group'].includes(n.privacy)||!Number.isInteger(n.day)||n.day< -1||n.day>=s.days)throw Error('Note invalide')}if(s.splitLink&&!validSplit(s.splitLink))throw Error('Lien de groupe invalide');return s}
